"""Пошаговые разборы главы 2.1: core_procs.c для трёх систем, list_procs.c и новые части brain.py.

Номера строк — по файлам tools/src21 (у brain.py — по фрагменту BRAIN_PART из ch21). Оформление — trace_html из walk11."""
from walk11 import like, trace_html
import viz as V


def build(hl, hl_py, cells, src, brain_part):
    W = {}

    W['win'] = trace_html('core_procs.c', 'win',
        'заполнить массив <code>out</code> строками «номер процесса, номер родителя, имя» для всех процессов системы. Список берётся из снимка, который делает Windows: функция проходит его от первой записи до последней.',
        [('1-3', 'Подключить заголовочные файлы',
          '<ul class="words"><li><code>windows.h</code> — основные функции и типы WinAPI;</li>'
          '<li><code>tlhelp32.h</code> — функции снимка процессов (Tool Help), их нет в <code>windows.h</code>;</li>'
          '<li><code>core.h</code> — <code>struct core_proc</code> и объявление функции ядра.</li></ul>'),
         ('5-7', 'Начать функцию',
          '<p><code>PROCESSENTRY32W pe</code> — одна запись снимка: номер процесса, номер родителя, имя файла и ещё несколько полей. Буква <code>W</code> в конце означает, что имя хранится в UTF-16. <code>found</code> — сколько процессов найдено, считается и тогда, когда место в <code>out</code> кончилось.</p>'),
         ('9-10', 'Проверить параметры',
          '<p>Без адреса для <code>count</code> функции некуда вернуть число процессов. Отрицательное <code>max</code> не имеет смысла. Пустой <code>out</code> допустим только при <code>max</code> = 0: так можно спросить «сколько процессов?», ничего не получая. В остальных случаях — код 87, <code>ERROR_INVALID_PARAMETER</code>, как в главе 1.1.</p>'),
         ('11-13', 'Сделать снимок',
          '<p><code>CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0)</code> просит Windows записать список процессов на этот момент. Ответ — <code>HANDLE</code>, номер объекта ядра, через который читают снимок. Второй параметр, 0, для списка процессов не используется.</p>'
          + V.steps(V.card('ядро Windows', 'процессы сейчас', '<small>список меняется каждую секунду</small>', 'sys'), V.arrow('снимок'),
                    V.card('объект ядра', 'snap', '<small>список на один момент, больше не меняется</small>', 'c'))
          + like('Фотография очереди: люди в очереди приходят и уходят, а на фотографии их можно спокойно пересчитать.')),
         ('15-20', 'Прочитать первую запись',
          '<p>Перед первым вызовом в <code>pe.dwSize</code> записывают размер структуры: по нему Windows определяет версию структуры записи. <code>Process32FirstW</code> копирует первую запись снимка в <code>pe</code>. Если она не прочиталась, функция берёт код ошибки, закрывает снимок и возвращает код.</p>'),
         ('21-30', 'Пройти снимок',
          '<p>Цикл <code>do … while</code> сначала выполняет тело, потом проверяет условие: первая запись уже прочитана и должна попасть в список. <code>Process32NextW</code> берёт следующую запись и возвращает <code>FALSE</code>, когда записи кончились.</p>'
          '<ul class="words"><li><code>th32ProcessID</code> — номер процесса, <code>th32ParentProcessID</code> — номер родителя;</li>'
          '<li><code>WideCharToMultiByte(CP_UTF8, …)</code> переводит имя из UTF-16 в UTF-8, как имя компьютера в главе 1.1. Если имя не помещается в 64 байта, функция возвращает 0, и последний байт делается нулём;</li>'
          '<li><code>found++</code> стоит вне <code>if</code>: процессы считаются до конца, даже когда место кончилось.</li></ul>'),
         ('32-34', 'Закрыть снимок и вернуть ответ',
          '<p><code>CloseHandle</code> освобождает объект снимка. В <code>*count</code> записывается, сколько процессов найдено. Если их больше, чем мест, функция возвращает 122, <code>ERROR_INSUFFICIENT_BUFFER</code>: первые <code>max</code> строк заполнены, а <code>count</code> говорит, сколько мест нужно.</p>')],
        [('снимок', 'CreateToolhelp32Snapshot'), ('запись за записью', 'Process32FirstW / NextW'), ('out[]', 'pid, ppid, имя'), ('count', 'сколько найдено')],
        hl(src('win')))

    W['mac'] = trace_html('core_procs.c', 'mac',
        'заполнить массив <code>out</code> строками «номер процесса, номер родителя, имя» для всех процессов системы. Сначала функция получает от ядра macOS номера всех процессов, потом про каждый номер спрашивает родителя и имя.',
        [('1-4', 'Подключить заголовочные файлы',
          '<ul class="words"><li><code>errno.h</code> — коды ошибок <code>EINVAL</code>, <code>ERANGE</code>;</li>'
          '<li><code>libproc.h</code> — функции <code>proc_listallpids</code> и <code>proc_pidinfo</code> — сведения о процессах от ядра macOS;</li>'
          '<li><code>stdio.h</code> — <code>snprintf</code>; <code>core.h</code> — структура и объявление.</li></ul>'),
         ('7-9', 'Подготовить место',
          '<p><code>static pid_t pids[8192]</code> — массив для номеров процессов, 32 КБ. Слово <code>static</code> кладёт его в память программы, где он хранится всё время работы; стопка вызовов для такого массива мала. <code>struct proc_bsdshortinfo si</code> — краткие сведения об одном процессе. <code>found</code> — счётчик найденных.</p>'),
         ('11-12', 'Проверить параметры',
          '<p>Те же проверки, что в других системах. Неверный параметр — код 22, <code>EINVAL</code>, как в главе 1.2.</p>'),
         ('13-15', 'Получить номера всех процессов',
          '<p><code>proc_listallpids(pids, sizeof pids)</code> записывает в массив номера всех процессов и возвращает, сколько записал. Второй параметр — размер массива в байтах: 8192 места по 4 байта, 32 768. При ошибке функция возвращает −1, а код ошибки лежит в <code>errno</code>.</p>'),
         ('17-19', 'Спросить про каждый процесс',
          '<p><code>proc_pidinfo(номер, PROC_PIDT_SHORTBSDINFO, 0, &amp;si, sizeof si)</code> заполняет <code>si</code> краткими сведениями о процессе и возвращает число записанных байт. Если байт меньше, чем размер структуры, процесс пропускается: он мог завершиться между двумя вызовами.</p>'
          + V.steps(V.card('шаг 13', 'pids[]', '<small>только номера: 0, 1, 4503, …</small>', 'sys'), V.arrow('номер'),
                    V.card('шаг 18', 'si', '<small>pbsi_ppid, pbsi_comm</small>', 'c'), V.arrow('копия'),
                    V.card('out[found]', 'pid, ppid, имя', '<small>80 байт</small>', 'py'))),
         ('20-25', 'Записать строку списка',
          '<p>Номер берётся из <code>pids[i]</code>, родитель — из <code>si.pbsi_ppid</code>. Имя <code>si.pbsi_comm</code> — массив из 16 байт (<code>MAXCOMLEN</code>), поэтому имя длиннее 15 символов приходит обрезанным. <code>snprintf(out, размер, "%s", имя)</code> копирует строку. Нулевой байт в конце она ставит всегда. <code>found++</code> стоит вне <code>if</code>: процессы считаются до конца.</p>'),
         ('27-28', 'Вернуть ответ',
          '<p>В <code>*count</code> — сколько процессов найдено. Если мест меньше, функция возвращает 34, <code>ERANGE</code> («результат не помещается»): первые <code>max</code> строк заполнены.</p>')],
        [('номера процессов', 'proc_listallpids'), ('про каждый', 'proc_pidinfo'), ('out[]', 'pid, ppid, имя'), ('count', 'сколько найдено')],
        hl(src('mac')))

    W['linux'] = trace_html('core_procs.c', 'linux',
        'заполнить массив <code>out</code> строками «номер процесса, номер родителя, имя» для всех процессов системы. В Linux у каждого процесса есть папка <code>/proc/номер</code>, а в ней файл <code>stat</code> со сведениями о процессе. Функция читает папку <code>/proc</code> и файл <code>stat</code> каждого процесса.',
        [('1-6', 'Подключить заголовочные файлы',
          '<ul class="words"><li><code>ctype.h</code> — <code>isdigit</code>, проверка «это цифра»;</li>'
          '<li><code>dirent.h</code> — чтение папки: <code>opendir</code>, <code>readdir</code>, <code>closedir</code>;</li>'
          '<li><code>errno.h</code>, <code>stdio.h</code>, <code>string.h</code> — коды ошибок, файлы и <code>snprintf</code>, поиск символа в строке.</li></ul>'),
         ('8-16', 'Прочитать файл stat',
          '<p>Вспомогательная функция <code>read_stat</code> объявлена <code>static</code>: она видна только внутри этого файла и не попадает в таблицу экспорта библиотеки.</p>'
          '<ul class="words"><li><code>snprintf(path, …, "/proc/%s/stat", pid)</code> собирает путь, например <code>/proc/305/stat</code>;</li>'
          '<li><code>fopen</code> открывает файл; если процесс уже завершился, файла нет, и функция возвращает −1;</li>'
          '<li><code>fread</code> читает до 511 байт, <code>line[len] = \'\\0\'</code> превращает их в строку C.</li></ul>'
          '<p>Начало файла для процесса из кадра:</p>'
          + cells([('305', 'pid', 'w'), ('(list_procs)', 'имя в скобках', 'w'), ('R', 'состояние', ''), ('229', 'ppid', 'w'), ('…', 'ещё 48 полей', '')])),
         ('18-21', 'Найти скобки вокруг имени',
          '<p>Имя процесса стоит в скобках и может содержать пробелы и скобки, например <code>(Web Content)</code>. Поэтому открывающую скобку ищут с начала строки функцией <code>strchr</code>, а закрывающую — с конца функцией <code>strrchr</code>. Всё между ними — имя.</p>'
          + like('Адрес на конверте читают от индекса до конца строки: где бы внутри ни стояла запятая, она часть адреса.')),
         ('22-28', 'Разобрать числа',
          '<p><code>sscanf(line, "%lld", &amp;pid_num)</code> читает первое число — номер процесса. <code>close + 2</code> — адрес сразу после «<code>) </code>». С него <code>"%*c %lld"</code> пропускает букву состояния (<code>*</code> — прочитать и не сохранять) и читает номер родителя. Имя копируется форматом <code>"%.*s"</code>: <code>*</code> берёт длину из параметра — число символов между скобками.</p>'),
         ('31-40', 'Открыть папку /proc',
          '<p>После тех же проверок параметров <code>opendir("/proc")</code> открывает папку. Это не папка на диске: её содержимое ядро Linux составляет в момент чтения.</p>'),
         ('42-50', 'Пройти все записи папки',
          '<p><code>readdir</code> возвращает следующую запись папки или <code>NULL</code>, когда записи кончились. В <code>/proc</code> есть и другие файлы, например <code>cpuinfo</code>, поэтому записи, которые начинаются не с цифры, пропускаются. Если <code>stat</code> не прочитался, процесс тоже пропускается. <code>out[found] = p</code> копирует все 80 байт структуры одной строкой.</p>'),
         ('51-53', 'Закрыть папку и вернуть ответ',
          '<p><code>closedir</code> освобождает папку. Дальше — как в других системах: <code>*count</code> и код 34, <code>ERANGE</code>, если мест меньше, чем процессов.</p>')],
        [('/proc', 'папки-номера'), ('/proc/N/stat', 'pid (имя) состояние ppid'), ('out[]', 'pid, ppid, имя'), ('count', 'сколько найдено')],
        hl(src('linux')))

    W['list'] = trace_html('list_procs.c', 'win mac linux',
        'вызвать <code>core_list_procs</code> из программы на C и напечатать список: так ядро проверяют до того, как его вызывает Python. Необязательный параметр командной строки задаёт число мест — с ним проверяется ответ «мест не хватило».',
        [('1-4', 'Подключить заголовочные файлы',
          '<p><code>inttypes.h</code> даёт форматы печати для типов точного размера: <code>PRId64</code> — формат для <code>int64_t</code>, на каждой системе свой (<code>lld</code> или <code>ld</code>). <code>stdlib.h</code> — <code>atoi</code>, перевод строки в число.</p>'),
         ('6-11', 'Подготовить массив',
          '<p><code>static struct core_proc procs[4096]</code> — 4096 мест по 80 байт, 320 КБ. Такой массив не помещают в стопку вызовов: её размер ограничен, в Windows по умолчанию 1 МБ на поток. Слово <code>static</code> кладёт массив в память программы.</p>'
          '<p><code>argc &gt; 1 ? atoi(argv[1]) : MAX</code> — если в командной строке есть параметр, число мест берётся из него, иначе 4096. Как устроены <code>argc</code> и <code>argv</code>, вы видели в ЛР 3.</p>'),
         ('13-15', 'Вызвать функцию ядра',
          '<p>Число мест ограничивается размером массива, чтобы ядро не писало за его конец. В функцию уходят адрес массива, число мест и адрес <code>count</code>.</p>'),
         ('16-19', 'Сообщить об ошибке',
          '<p>Если код не 0, программа печатает код, сколько мест нужно и сколько было, и завершается с кодом 1.</p>'),
         ('20-23', 'Напечатать список',
          '<p>Каждая строка — номер процесса и номер родителя шириной 7 символов и имя. <code>"%7" PRId64</code> — две строки подряд, компилятор склеивает их в одну: <code>"%7lld"</code> или <code>"%7ld"</code>. Последняя строка — число процессов и размер одной записи.</p>')],
        [('procs[4096]', 'места для списка'), ('core_list_procs', 'ядро'), ('печать', 'pid ppid имя'), ('итог', 'processes N, sizeof 80')],
        hl(src('list')))

    W['brain'] = trace_html('brain.py · новые части', 'win mac linux',
        'получить список процессов из ядра, сколько бы их ни было, и найти цепочку родителей процесса. Цепочка — первое, что агент сообщает о себе: кто его запустил.',
        [('1-6', 'Описать структуру процесса',
          '<p>Класс <code>CoreProc</code> повторяет <code>struct core_proc</code> из <code>core.h</code>: два поля по 8 байт и массив из 64 байт. По нему ctypes посчитает размер 80.</p>'),
         ('8-10', 'Задать типы функции',
          '<p>Три параметра — указатель на массив структур, число мест <code>c_int32</code> и указатель на <code>c_int32</code>. <code>TOO_SMALL</code> — код «мест не хватило»: 122 в Windows, <code>errno.ERANGE</code> (34) в macOS и Linux.</p>'),
         ('12-16', 'Вызвать ядро',
          '<p><code>CoreProc * room</code> — тип «массив из <code>room</code> структур», скобки <code>()</code> создают такой массив, заполненный нулями. <code>c_int32()</code> — число, куда ядро запишет <code>count</code>. Массив передаётся без <code>byref</code>: в ctypes, как и в C, массив передаётся адресом первого элемента.</p>'),
         ('17-19', 'Вернуть список словарей',
          '<p>При коде 0 из первых <code>count</code> структур собирается список словарей. <code>decode("utf-8", "replace")</code> заменяет знаком «�» байты, которые не читаются как UTF-8: в macOS обрезанное имя может закончиться на половине русской буквы.</p>'),
         ('20-22', 'Повторить с нужным местом',
          '<p>Любой код, кроме «мест не хватило», становится исключением. При <code>TOO_SMALL</code> в <code>count</code> лежит нужное число мест. Новый размер берётся с запасом 64: пока идёт второй вызов, могут появиться новые процессы. Цикл <code>while True</code> повторяет вызов, пока места не хватит.</p>'
          + V.steps(V.card('вызов 1', 'room = 256', '<small>на кадре macOS процессов 491</small>', 'bad'), V.arrow('код 34, count = 491'),
                    V.card('вызов 2', 'room = 555', '<small>491 + 64</small>', 'ok'), V.arrow('код 0'),
                    V.card('Python', 'список из 491', '', 'py'))),
         ('24-26', 'Сделать словарь по номерам',
          '<p><code>{p["pid"]: p for p in procs}</code> — словарь «номер → процесс». По нему родитель находится сразу, без перебора списка.</p>'),
         ('27-33', 'Подняться по родителям',
          '<p>Цикл берёт процесс, добавляет его в цепочку и переходит к родителю. Остановок три:</p>'
          '<ul class="words"><li>номера родителя нет в списке — родитель уже завершился или это процесс 1 в контейнере;</li>'
          '<li>процесс сам себе родитель — так записан процесс 0 в Windows и macOS;</li>'
          '<li>в цепочке 64 процесса — защита от круга: в Windows номер завершённого процесса может достаться новому, и цепочка может замкнуться.</li></ul>')],
        [('ядро', 'core_list_procs'), ('список словарей', 'pid, ppid, name'), ('словарь по pid', ''), ('цепочка', 'я → родитель → …')],
        hl_py(brain_part))
    return W
